  },
  AvgCommunicate_150103_Content_14 = {
    Text = "และองค์เทพราชาจะงมเก็บเศษชิ้นส่วนเหล่านี้จากม่านฝน, หลังจากผ่านการหลับใหลอันยาวนาน, จึงจะสร้างโลกขึ้นใหม่."
