  AvgCommunicate_150103_Content_2 = {
    Text = "คิดดูแล้ว, เจ้าได้ก้าวผ่านจุดเปลี่ยนแห่งชะตากรรม และมาถึงดินแดนแห่งพันธสัญญาที่แสวงหามานาน."
